def solve(a: str, b: str) -> int:
    n, m = len(a), len(b)
    # DP with O(min(n,m)) space using the shorter string as columns
    if m < n:
        # swap to ensure m >= n for less memory in inner loop
        a, b = b, a
        n, m = m, n
    dp = list(range(m + 1))
    for i in range(1, n + 1):
        prev = dp[0]
        dp[0] = i
        for j in range(1, m + 1):
            cur = dp[j]
            if a[i - 1] == b[j - 1]:
                dp[j] = prev
            else:
                dp[j] = 1 + min(prev, dp[j - 1], dp[j])
            prev = cur
    return dp[m]

