def solve(grid):
    """Count islands (connected components of 1s) with 4-directional adjacency.
    Works for non‑rectangular grids as well.
    """
    if not grid:
        return 0
    visited = set()
    n = len(grid)
    def neighbors(r, c):
        # up
        if r > 0 and c < len(grid[r-1]):
            yield r-1, c
        # down
        if r+1 < n and c < len(grid[r+1]):
            yield r+1, c
        # left
        if c > 0:
            yield r, c-1
        # right
        if c+1 < len(grid[r]):
            yield r, c+1
    def dfs(sr, sc):
        stack = [(sr, sc)]
        while stack:
            r, c = stack.pop()
            if (r, c) in visited:
                continue
            visited.add((r, c))
            for nr, nc in neighbors(r, c):
                if grid[nr][nc] == 1 and (nr, nc) not in visited:
                    stack.append((nr, nc))
    count = 0
    for i, row in enumerate(grid):
        for j, val in enumerate(row):
            if val == 1 and (i, j) not in visited:
                count += 1
                dfs(i, j)
    return count

