    # Levenshtein distance DP with O(min(n,m)) space
    n, m = len(a), len(b)
    if n < m:
        # ensure a is the longer string to use less space for dp (columns = smaller)
        a, b = b, a
        n, m = m, n
    dp = list(range(m + 1))
    for i in range(1, n + 1):
        prev = dp[0]
        dp[0] = i
        for j in range(1, m + 1):
            cur = dp[j]
            if a[i - 1] == b[j - 1]:
                dp[j] = prev
            else:
                dp[j] = 1 + min(prev, dp[j - 1], dp[j])
            prev = cur
    return dp[m]
